I = importlib

metadata = Hash()

balances = Hash(default_value=0)
allowances = Hash(default_value=0)

MIN_SUPPLY = 10_000_000
BURN_ADDRESS = 'BURN'

@construct
def seed():
    balances[ctx.caller] = 10_000_000_000

    metadata['token_name'] = "TEST"
    metadata['token_symbol'] = "TTTTT"
    metadata['operator'] = ctx.caller
    metadata['dex'] = 'con_rocketswap_official_v1_1'
    metadata['threshold'] = 2
    metadata['bonus'] = 0.03
    metadata['burn'] = 0.001

@export
def change_metadata(key: str, value: Any):
    assert ctx.caller == metadata['operator'], 'Only owner can set metadata!'
    metadata[key] = value

@export
def transfer(amount: float, to: str):
    assert amount > 0, 'Cannot send negative balances!'
    assert balances[ctx.caller] >= amount, 'Not enough coins to send!'

    balances[ctx.caller] -= amount
    balances[to] += amount

@export
def approve(amount: float, to: str):
    assert amount > 0, 'Cannot send negative balances!'
    allowances[ctx.caller, to] += amount

@export
def transfer_from(amount: float, to: str, main_account: str):
    assert amount > 0, 'Cannot send negative balances!'
    assert allowances[main_account, ctx.caller] >= amount, f'You approved {allowances[main_account, ctx.caller]} but need {amount}'
    assert balances[main_account] >= amount, 'Not enough coins to send!'

    allowances[main_account, ctx.caller] -= amount
    balances[main_account] -= amount
    balances[to] += amount

@export
def redeem(token_contract: str, token_amount: float):
    dex_prices = ForeignHash(foreign_contract=metadata['dex'], foreign_name='prices')

    assert token_contract in dex_prices, 'Token not available on DEX'

    current_value = token_amount * dex_prices[token_contract]

    assert current_value >= metadata['threshold'], f'Contribution must be worth at least {metadata["threshold"]} TAU'

    actual_value = I.import_module(metadata['dex']).sell(token_contract, token_amount)

    I.import_module(metadata['dex']).add_liquidity(ctx.this, actual_value)

    king_amount = actual_value / dex_prices[ctx.this]
    king_total = king_amount + (king_amount * metadata['bonus'])

    transfer(amount=king_total, to=ctx.caller)
    transfer(amount=balances[ctx.this] * metadata['burn'], to=BURN_ADDRESS)

    assert int(total_supply()) >= MIN_SUPPLY, f'Can not exceed minimum supply of {MIN_SUPPLY} KING'

@export
def burn(amount: float):
    transfer(amount=amount, to=BURN_ADDRESS)
    assert_owner()

@export
def remove_liquidity(amount: float):
    I.import_module(metadata['dex']).remove_liquidity(ctx.this, amount)
    assert_owner()

@export
def withdraw(contract: str, amount: float):
    if contract == ctx.this:
        transfer(amount=amount, to=ctx.caller)
    else:
        I.import_module(contract).transfer(amount=amount, to=ctx.caller)
    assert_owner()

@export
def total_supply():
    return f'{sum(balances.all())}'

def assert_owner():
    assert ctx.caller == metadata['operator'], 'Only executable by owner!'
